CREATE TRIGGER "time_block_one_running_per_kind_insert"
BEFORE INSERT ON "time_block"
WHEN NEW."end_utc" IS NULL AND NEW."deleted_at" IS NULL
BEGIN
  SELECT RAISE(ABORT, 'a block of this kind is already running')
  WHERE EXISTS (
    SELECT 1 FROM "time_block"
    WHERE "kind" = NEW."kind" AND "end_utc" IS NULL
      AND "deleted_at" IS NULL AND "id" <> NEW."id"
  );
END;

CREATE TRIGGER "time_block_one_running_per_kind_update"
BEFORE UPDATE OF "end_utc", "deleted_at", "kind" ON "time_block"
WHEN NEW."end_utc" IS NULL AND NEW."deleted_at" IS NULL
BEGIN
  SELECT RAISE(ABORT, 'a block of this kind is already running')
  WHERE EXISTS (
    SELECT 1 FROM "time_block"
    WHERE "kind" = NEW."kind" AND "end_utc" IS NULL
      AND "deleted_at" IS NULL AND "id" <> NEW."id"
  );
END;
